import{_ as a,o as t,c as o,ag as i}from"./chunks/framework.B7PviQjB.js";const m=JSON.parse('{"title":"Troubleshooting","description":"Fix common problems with signing in, saving, share links, uploads, templates, version history, sheets, docs, and the desktop app, by the message you see.","frontmatter":{"title":"Troubleshooting","description":"Fix common problems with signing in, saving, share links, uploads, templates, version history, sheets, docs, and the desktop app, by the message you see.","type":"troubleshooting"},"headers":[],"relativePath":"start/troubleshooting.md","filePath":"start/troubleshooting.md"}'),r={name:"start/troubleshooting.md"};function s(n,e,h,l,d,c){return t(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h1><p>Find the message or symptom you see, then work through the fixes in order.</p><ul><li>Sign in: <a href="#that-sign-in-link-expired-or-was-started-in-another-tab">sign-in link expired</a>, <a href="#an-account-already-exists-for-that-email-address-under-the-other-sign-in-provider">account exists under the other provider</a>, <a href="#that-account-has-no-verified-email-address">no verified email</a></li><li>Saving: <a href="#the-header-says-not-saved">Not saved</a>, <a href="#the-header-says-reconnecting">Reconnecting…</a>, <a href="#leave-without-saving-appears">Leave without saving?</a></li><li>Sharing: <a href="#link-unavailable">Link unavailable</a>, <a href="#a-share-link-opens-read-only">read-only link</a>, <a href="#you-can-t-choose-editor-in-the-share-dialog">can&#39;t choose Editor</a></li><li>Documents: <a href="#a-document-disappeared">a document disappeared</a>, <a href="#you-can-only-move-documents-you-own">can&#39;t move or delete</a>, <a href="#file-is-larger-than-the-100-mb-limit">upload too large</a>, <a href="#an-uploaded-md-file-didn-t-become-a-note">Markdown upload</a></li><li>Sheets: <a href="#select-at-least-2-rows-and-2-columns">chart needs 2 rows and 2 columns</a>, <a href="#only-select-queries-are-allowed">query refused</a>, <a href="#local-lakehouse-paths-are-disabled-on-this-server">local lakehouse paths disabled</a></li><li>Docs: <a href="#couldn-t-upload-the-image">image upload failed</a>, <a href="#image-url-must-start-with-http-or-https">image URL refused</a>, <a href="#margins-must-be-zero-or-a-positive-number-of-inches">margins refused</a>, <a href="#the-cursor-left-this-link-click-it-again-to-edit-it">link edit refused</a></li><li>Desktop app: <a href="#this-server-is-too-old-for-desktop-sign-in">server too old</a>, <a href="#this-server-has-desktop-sign-in-turned-off">sign-in turned off</a>, <a href="#sign-in-timed-out-try-again">sign-in timed out</a>, <a href="#can-t-reach-appears-in-the-desktop-app">can&#39;t reach the server</a>, <a href="#a-mac-says-wafflebase-is-damaged-or-can-t-be-opened">Mac warning</a></li><li>Other: <a href="#template-not-found">Template not found</a>, <a href="#version-history-is-missing">no version history</a>, <a href="#a-restore-is-already-in-progress">restore in progress</a>, <a href="#couldn-t-update-the-workspace">workspace settings</a></li></ul><h2 id="that-sign-in-link-expired-or-was-started-in-another-tab" tabindex="-1"><code>That sign-in link expired or was started in another tab</code> <a class="header-anchor" href="#that-sign-in-link-expired-or-was-started-in-another-tab" aria-label="Permalink to &quot;`That sign-in link expired or was started in another tab`&quot;">​</a></h2><h3 id="what-it-means" tabindex="-1">What it means <a class="header-anchor" href="#what-it-means" aria-label="Permalink to &quot;What it means&quot;">​</a></h3><p>The sign-in took too long, or you started a second sign-in in another tab, which replaced the first.</p><h3 id="try-this" tabindex="-1">Try this <a class="header-anchor" href="#try-this" aria-label="Permalink to &quot;Try this&quot;">​</a></h3><ol><li>Close any other Wafflebase sign-in tabs.</li><li>Click <strong>Continue with GitHub</strong> (or <strong>Continue with Google</strong>) again in one tab.</li></ol><h2 id="an-account-already-exists-for-that-email-address-under-the-other-sign-in-provider" tabindex="-1"><code>An account already exists for that email address under the other sign-in provider</code> <a class="header-anchor" href="#an-account-already-exists-for-that-email-address-under-the-other-sign-in-provider" aria-label="Permalink to &quot;`An account already exists for that email address under the other sign-in provider`&quot;">​</a></h2><h3 id="what-it-means-1" tabindex="-1">What it means <a class="header-anchor" href="#what-it-means-1" aria-label="Permalink to &quot;What it means&quot;">​</a></h3><p>You first signed in with the other provider (GitHub or Google) using the same email address.</p><h3 id="try-this-1" tabindex="-1">Try this <a class="header-anchor" href="#try-this-1" aria-label="Permalink to &quot;Try this&quot;">​</a></h3><ol><li>Sign in once with the provider you used first.</li><li>Sign out, then sign in with the new provider. It works from now on.</li></ol><h2 id="that-account-has-no-verified-email-address" tabindex="-1"><code>That account has no verified email address</code> <a class="header-anchor" href="#that-account-has-no-verified-email-address" aria-label="Permalink to &quot;`That account has no verified email address`&quot;">​</a></h2><h3 id="what-it-means-2" tabindex="-1">What it means <a class="header-anchor" href="#what-it-means-2" aria-label="Permalink to &quot;What it means&quot;">​</a></h3><p>Wafflebase signs you in by your email address, and the provider reports none that is verified. A related message, <code>That account did not share an email address</code>, means the provider shared no address at all.</p><h3 id="try-this-2" tabindex="-1">Try this <a class="header-anchor" href="#try-this-2" aria-label="Permalink to &quot;Try this&quot;">​</a></h3><ol><li>Verify your email address in your GitHub or Google account settings.</li><li>Sign in again, or try the other provider.</li></ol><h2 id="the-header-says-not-saved" tabindex="-1">The header says <strong>Not saved</strong> <a class="header-anchor" href="#the-header-says-not-saved" aria-label="Permalink to &quot;The header says **Not saved**&quot;">​</a></h2><h3 id="what-it-means-3" tabindex="-1">What it means <a class="header-anchor" href="#what-it-means-3" aria-label="Permalink to &quot;What it means&quot;">​</a></h3><p>Your recent changes haven&#39;t reached the server. They exist only in this browser tab, so closing or reloading it loses them. A <strong>Not saved</strong> notice explains which case you&#39;re in:</p><ul><li><em>Your connection dropped</em>: the changes sync when the connection returns.</li><li><em>The server rejected your recent changes</em>: the changes won&#39;t sync on their own.</li></ul><h3 id="try-this-3" tabindex="-1">Try this <a class="header-anchor" href="#try-this-3" aria-label="Permalink to &quot;Try this&quot;">​</a></h3><ol><li>Keep the tab open. Don&#39;t reload it.</li><li>If your connection dropped, reconnect to the network and wait for the header to show <strong>Saved</strong>.</li><li>If the server rejected the changes, copy the text you added somewhere safe, such as another app. Then reload the document and add it again.</li><li>If you opened the document with a share link, ask its owner whether the link was revoked or changed to a viewer link.</li></ol><h2 id="the-header-says-reconnecting" tabindex="-1">The header says <strong>Reconnecting…</strong> <a class="header-anchor" href="#the-header-says-reconnecting" aria-label="Permalink to &quot;The header says **Reconnecting…** {#the-header-says-reconnecting}&quot;">​</a></h2><h3 id="what-it-means-4" tabindex="-1">What it means <a class="header-anchor" href="#what-it-means-4" aria-label="Permalink to &quot;What it means&quot;">​</a></h3><p>The connection to the server dropped, but none of your changes are waiting to be sent. Nothing is lost.</p><h3 id="try-this-4" tabindex="-1">Try this <a class="header-anchor" href="#try-this-4" aria-label="Permalink to &quot;Try this&quot;">​</a></h3><ol><li>Check your network connection.</li><li>Wait. The header returns to <strong>Saved</strong> when the connection comes back.</li></ol><h2 id="leave-without-saving-appears" tabindex="-1"><strong>Leave without saving?</strong> appears <a class="header-anchor" href="#leave-without-saving-appears" aria-label="Permalink to &quot;**Leave without saving?** appears&quot;">​</a></h2><h3 id="what-it-means-5" tabindex="-1">What it means <a class="header-anchor" href="#what-it-means-5" aria-label="Permalink to &quot;What it means&quot;">​</a></h3><p>You tried to leave a document while some of your changes hadn&#39;t reached the server. Leaving now loses them.</p><h3 id="try-this-5" tabindex="-1">Try this <a class="header-anchor" href="#try-this-5" aria-label="Permalink to &quot;Try this&quot;">​</a></h3><ol><li>Click <strong>Stay</strong>.</li><li>Wait for the header to show <strong>Saved</strong>, then leave.</li><li>If it shows <strong>Not saved</strong>, see <a href="#the-header-says-not-saved">The header says Not saved</a>.</li></ol><h2 id="link-unavailable" tabindex="-1"><strong>Link unavailable</strong> <a class="header-anchor" href="#link-unavailable" aria-label="Permalink to &quot;**Link unavailable**&quot;">​</a></h2><h3 id="what-it-means-6" tabindex="-1">What it means <a class="header-anchor" href="#what-it-means-6" aria-label="Permalink to &quot;What it means&quot;">​</a></h3><p>The share link no longer works. The page explains why:</p><ul><li><code>Share link not found</code>: the link was revoked, or its document was moved to the Trash.</li><li><code>Share link has expired</code>: the link&#39;s expiration time has passed.</li></ul><h3 id="try-this-6" tabindex="-1">Try this <a class="header-anchor" href="#try-this-6" aria-label="Permalink to &quot;Try this&quot;">​</a></h3><ol><li>Check that you copied the whole link.</li><li>Ask the document&#39;s owner for a new link. If the document is in the Trash, restoring it brings its links back.</li></ol><h2 id="a-share-link-opens-read-only" tabindex="-1">A share link opens read-only <a class="header-anchor" href="#a-share-link-opens-read-only" aria-label="Permalink to &quot;A share link opens read-only&quot;">​</a></h2><h3 id="what-it-means-7" tabindex="-1">What it means <a class="header-anchor" href="#what-it-means-7" aria-label="Permalink to &quot;What it means&quot;">​</a></h3><p>The link is a viewer link. The header shows a <strong>View only</strong> badge, and you can read the document but not change it.</p><h3 id="try-this-7" tabindex="-1">Try this <a class="header-anchor" href="#try-this-7" aria-label="Permalink to &quot;Try this&quot;">​</a></h3><ol><li>Ask the document&#39;s owner for an editor link.</li><li>If you&#39;re in the same workspace, open the document from your documents list instead. Members can edit every document there.</li></ol><h2 id="you-can-t-choose-editor-in-the-share-dialog" tabindex="-1">You can&#39;t choose <strong>Editor</strong> in the Share dialog <a class="header-anchor" href="#you-can-t-choose-editor-in-the-share-dialog" aria-label="Permalink to &quot;You can&#39;t choose **Editor** in the Share dialog&quot;">​</a></h2><h3 id="what-it-means-8" tabindex="-1">What it means <a class="header-anchor" href="#what-it-means-8" aria-label="Permalink to &quot;What it means&quot;">​</a></h3><p>Only the document&#39;s author or a workspace owner can create editor links. The dialog says <code>Only the document owner or a workspace owner can create editor links.</code></p><h3 id="try-this-8" tabindex="-1">Try this <a class="header-anchor" href="#try-this-8" aria-label="Permalink to &quot;Try this&quot;">​</a></h3><ol><li>Create a <strong>Viewer</strong> link instead, if reading is enough.</li><li>Ask the author or a workspace owner to create the editor link.</li></ol><h2 id="a-document-disappeared" tabindex="-1">A document disappeared <a class="header-anchor" href="#a-document-disappeared" aria-label="Permalink to &quot;A document disappeared&quot;">​</a></h2><h3 id="what-it-means-9" tabindex="-1">What it means <a class="header-anchor" href="#what-it-means-9" aria-label="Permalink to &quot;What it means&quot;">​</a></h3><p>Someone probably moved it to the Trash, or moved it into a folder.</p><h3 id="try-this-9" tabindex="-1">Try this <a class="header-anchor" href="#try-this-9" aria-label="Permalink to &quot;Try this&quot;">​</a></h3><ol><li>Check your folders. <strong>Search by title...</strong> at the top of the documents list searches only the folder you&#39;re in.</li><li>Open <strong>Trash</strong> in the sidebar. The document&#39;s author or a workspace owner can click <strong>Restore</strong>.</li><li>Ask a workspace owner whether it was deleted forever. That can&#39;t be undone.</li></ol><h2 id="you-can-only-move-documents-you-own" tabindex="-1"><code>You can only move documents you own</code> <a class="header-anchor" href="#you-can-only-move-documents-you-own" aria-label="Permalink to &quot;`You can only move documents you own`&quot;">​</a></h2><h3 id="what-it-means-10" tabindex="-1">What it means <a class="header-anchor" href="#what-it-means-10" aria-label="Permalink to &quot;What it means&quot;">​</a></h3><p>Moving a document, or moving it to the Trash, needs its author or a workspace owner. The message <code>You can only delete documents you own</code> means the same thing.</p><h3 id="try-this-10" tabindex="-1">Try this <a class="header-anchor" href="#try-this-10" aria-label="Permalink to &quot;Try this&quot;">​</a></h3><ol><li>Check the <strong>Owner</strong> column in the documents list to see who created each document.</li><li>Ask that person or a workspace owner to move or delete it.</li></ol><h2 id="file-is-larger-than-the-100-mb-limit" tabindex="-1"><code>File is larger than the 100 MB limit</code> <a class="header-anchor" href="#file-is-larger-than-the-100-mb-limit" aria-label="Permalink to &quot;`File is larger than the 100 MB limit`&quot;">​</a></h2><h3 id="what-it-means-11" tabindex="-1">What it means <a class="header-anchor" href="#what-it-means-11" aria-label="Permalink to &quot;What it means&quot;">​</a></h3><p>Uploads are limited to 100 MB per file, and 25 MB for images. An image over its limit shows <code>File is larger than the 25 MB limit</code> instead. The file is not uploaded, and the upload panel can&#39;t retry it.</p><h3 id="try-this-11" tabindex="-1">Try this <a class="header-anchor" href="#try-this-11" aria-label="Permalink to &quot;Try this&quot;">​</a></h3><ol><li>Compress the file or split it into smaller files.</li><li>Upload the smaller file again with <strong>New &gt; Upload files…</strong>.</li></ol><h2 id="an-uploaded-md-file-didn-t-become-a-note" tabindex="-1">An uploaded <code>.md</code> file didn&#39;t become a note <a class="header-anchor" href="#an-uploaded-md-file-didn-t-become-a-note" aria-label="Permalink to &quot;An uploaded `.md` file didn&#39;t become a note&quot;">​</a></h2><h3 id="what-it-means-12" tabindex="-1">What it means <a class="header-anchor" href="#what-it-means-12" aria-label="Permalink to &quot;What it means&quot;">​</a></h3><p>Uploading a Markdown file stores it as a file you can download. It doesn&#39;t create a note.</p><h3 id="try-this-12" tabindex="-1">Try this <a class="header-anchor" href="#try-this-12" aria-label="Permalink to &quot;Try this&quot;">​</a></h3><ol><li>Open the file, copy its text, and paste it into a new note (<strong>New &gt; New note</strong>).</li><li>To turn a Markdown file into a note from the command line, use <code>wafflebase notes import</code>. See <a href="/docs/developers/cli/documents.html#import-a-markdown-file">Import a Markdown file</a>.</li></ol><h2 id="select-at-least-2-rows-and-2-columns" tabindex="-1"><code>Select at least 2 rows and 2 columns.</code> <a class="header-anchor" href="#select-at-least-2-rows-and-2-columns" aria-label="Permalink to &quot;`Select at least 2 rows and 2 columns.` {#select-at-least-2-rows-and-2-columns}&quot;">​</a></h2><h3 id="what-it-means-13" tabindex="-1">What it means <a class="header-anchor" href="#what-it-means-13" aria-label="Permalink to &quot;What it means&quot;">​</a></h3><p>A chart needs a range at least 2 cells tall and 2 cells wide: one column for labels and one for values, with a header row. A related message, <code>Select a cell range to insert a chart.</code>, means you selected whole rows, whole columns, or the whole sheet instead of cells.</p><h3 id="try-this-13" tabindex="-1">Try this <a class="header-anchor" href="#try-this-13" aria-label="Permalink to &quot;Try this&quot;">​</a></h3><ol><li>Drag across the data, including the header row and the label column.</li><li>Click <strong>Insert chart</strong> again.</li></ol><p>See <a href="/docs/sheets/charts.html">Add a chart</a>.</p><h2 id="only-select-queries-are-allowed" tabindex="-1"><code>Only SELECT queries are allowed</code> <a class="header-anchor" href="#only-select-queries-are-allowed" aria-label="Permalink to &quot;`Only SELECT queries are allowed` {#only-select-queries-are-allowed}&quot;">​</a></h2><h3 id="what-it-means-14" tabindex="-1">What it means <a class="header-anchor" href="#what-it-means-14" aria-label="Permalink to &quot;What it means&quot;">​</a></h3><p>A data source tab only reads from the database. Each query must be one statement that starts with <code>SELECT</code> or <code>WITH</code>. Two related messages mean the same rule: <code>Forbidden keyword: …</code> (the query contains a word such as <code>INSERT</code>, <code>UPDATE</code>, or <code>DELETE</code>, even inside quotes) and <code>Multiple statements are not allowed</code>.</p><h3 id="try-this-14" tabindex="-1">Try this <a class="header-anchor" href="#try-this-14" aria-label="Permalink to &quot;Try this&quot;">​</a></h3><ol><li>Start the query with <code>SELECT</code> or <code>WITH</code>.</li><li>Remove any statement after the first <code>;</code>.</li><li>Remove or rename anything that spells a refused word on its own, such as a quoted <code>&#39;delete&#39;</code>.</li><li>Click <strong>Execute</strong> again.</li></ol><p>See <a href="/docs/sheets/connect-a-database.html">Connect a database</a>.</p><h2 id="local-lakehouse-paths-are-disabled-on-this-server" tabindex="-1"><code>Local lakehouse paths are disabled on this server</code> <a class="header-anchor" href="#local-lakehouse-paths-are-disabled-on-this-server" aria-label="Permalink to &quot;`Local lakehouse paths are disabled on this server` {#local-lakehouse-paths-are-disabled-on-this-server}&quot;">​</a></h2><h3 id="what-it-means-15" tabindex="-1">What it means <a class="header-anchor" href="#what-it-means-15" aria-label="Permalink to &quot;What it means&quot;">​</a></h3><p>The connection uses <strong>Local filesystem (server-configured)</strong>, and the server&#39;s operator hasn&#39;t turned local paths on. A related message, <code>… is not allowed by the server</code>, means a custom endpoint isn&#39;t on the operator&#39;s allowlist.</p><h3 id="try-this-15" tabindex="-1">Try this <a class="header-anchor" href="#try-this-15" aria-label="Permalink to &quot;Try this&quot;">​</a></h3><ol><li>If the table lives in cloud storage, change <strong>Storage</strong> to that service and enter its path.</li><li>Otherwise, ask the person who runs your Wafflebase server to turn on local paths or allow the endpoint. Operators: see <a href="/docs/developers/self-hosting/optional-features.html#connect-databases-and-lakehouse-tables">Connect databases and lakehouse tables</a>.</li></ol><p>See <a href="/docs/sheets/lakehouse.html">Read lakehouse tables</a>.</p><h2 id="couldn-t-upload-the-image" tabindex="-1"><code>Couldn&#39;t upload the image</code> <a class="header-anchor" href="#couldn-t-upload-the-image" aria-label="Permalink to &quot;`Couldn&#39;t upload the image` {#couldn-t-upload-the-image}&quot;">​</a></h2><h3 id="what-it-means-16" tabindex="-1">What it means <a class="header-anchor" href="#what-it-means-16" aria-label="Permalink to &quot;What it means&quot;">​</a></h3><p>The image didn&#39;t reach the server, so nothing was inserted. The message may end with more detail. Common causes: the file is over 10 MB, it isn&#39;t a PNG, JPEG, GIF, or WebP image, or your connection dropped.</p><h3 id="try-this-16" tabindex="-1">Try this <a class="header-anchor" href="#try-this-16" aria-label="Permalink to &quot;Try this&quot;">​</a></h3><ol><li>Check the file&#39;s format and size. Save it as PNG or JPEG, or make it smaller, if needed.</li><li>Check your connection, then insert the image again.</li></ol><p>See <a href="/docs/docs-editor/images.html">Add and edit images</a>.</p><h2 id="image-url-must-start-with-http-or-https" tabindex="-1"><code>Image URL must start with http:// or https://</code> <a class="header-anchor" href="#image-url-must-start-with-http-or-https" aria-label="Permalink to &quot;`Image URL must start with http:// or https://` {#image-url-must-start-with-http-or-https}&quot;">​</a></h2><h3 id="what-it-means-17" tabindex="-1">What it means <a class="header-anchor" href="#what-it-means-17" aria-label="Permalink to &quot;What it means&quot;">​</a></h3><p>The address you entered under <strong>By URL…</strong> isn&#39;t a full web address. A related message, <code>Couldn&#39;t load the image</code>, means the address works but doesn&#39;t lead to an image the browser can show.</p><h3 id="try-this-17" tabindex="-1">Try this <a class="header-anchor" href="#try-this-17" aria-label="Permalink to &quot;Try this&quot;">​</a></h3><ol><li>Copy the image&#39;s own address, including <code>https://</code>. In most browsers, right-click the image and select <strong>Copy image address</strong>.</li><li>Paste it into <strong>By URL…</strong> again.</li><li>If it still fails, download the image and upload it instead.</li></ol><p>See <a href="/docs/docs-editor/images.html">Add and edit images</a>.</p><h2 id="margins-must-be-zero-or-a-positive-number-of-inches" tabindex="-1"><code>Margins must be zero or a positive number of inches.</code> <a class="header-anchor" href="#margins-must-be-zero-or-a-positive-number-of-inches" aria-label="Permalink to &quot;`Margins must be zero or a positive number of inches.` {#margins-must-be-zero-or-a-positive-number-of-inches}&quot;">​</a></h2><h3 id="what-it-means-18" tabindex="-1">What it means <a class="header-anchor" href="#what-it-means-18" aria-label="Permalink to &quot;What it means&quot;">​</a></h3><p>A margin box in <strong>Page setup</strong> is empty or holds something other than a plain number, such as <code>1 in</code>, <code>-1</code>, or <code>1,5</code>. <strong>Apply</strong> stays off until you fix it. The related messages <code>Left and right margins must leave room for content.</code> and <code>Top and bottom margins must leave room for content.</code> mean the margins are too wide for the page.</p><h3 id="try-this-18" tabindex="-1">Try this <a class="header-anchor" href="#try-this-18" aria-label="Permalink to &quot;Try this&quot;">​</a></h3><ol><li>Enter each margin as a plain number of inches, such as <code>1</code> or <code>0.75</code>.</li><li>If a &quot;leave room&quot; message appears, make the named pair of margins smaller.</li><li>Click <strong>Apply</strong>.</li></ol><p>See <a href="/docs/docs-editor/page-layout.html#change-margins">Change margins</a>.</p><h2 id="the-cursor-left-this-link-click-it-again-to-edit-it" tabindex="-1"><code>The cursor left this link. Click it again to edit it.</code> <a class="header-anchor" href="#the-cursor-left-this-link-click-it-again-to-edit-it" aria-label="Permalink to &quot;`The cursor left this link. Click it again to edit it.` {#the-cursor-left-this-link-click-it-again-to-edit-it}&quot;">​</a></h2><h3 id="what-it-means-19" tabindex="-1">What it means <a class="header-anchor" href="#what-it-means-19" aria-label="Permalink to &quot;What it means&quot;">​</a></h3><p>The cursor moved out of the link while you were editing its address, so <strong>Apply</strong> didn&#39;t change anything. The address you typed is still in the box.</p><h3 id="try-this-19" tabindex="-1">Try this <a class="header-anchor" href="#try-this-19" aria-label="Permalink to &quot;Try this&quot;">​</a></h3><ol><li>Copy the address from the box.</li><li>Click inside the link again, then click <strong>Edit link</strong> (pencil).</li><li>Paste the address and click <strong>Apply</strong>.</li></ol><p>See <a href="/docs/docs-editor/format-text.html#add-a-link">Add a link</a>.</p><h2 id="template-not-found" tabindex="-1"><strong>Template not found</strong> <a class="header-anchor" href="#template-not-found" aria-label="Permalink to &quot;**Template not found**&quot;">​</a></h2><h3 id="what-it-means-20" tabindex="-1">What it means <a class="header-anchor" href="#what-it-means-20" aria-label="Permalink to &quot;What it means&quot;">​</a></h3><p>The template link is wrong, or the template was unpublished.</p><h3 id="try-this-20" tabindex="-1">Try this <a class="header-anchor" href="#try-this-20" aria-label="Permalink to &quot;Try this&quot;">​</a></h3><ol><li>Check that you copied the whole link.</li><li>Click <strong>Browse the gallery</strong> to find a similar template.</li><li>Ask the person who shared it whether it is still published.</li></ol><h2 id="version-history-is-missing" tabindex="-1">Version history is missing <a class="header-anchor" href="#version-history-is-missing" aria-label="Permalink to &quot;Version history is missing&quot;">​</a></h2><h3 id="what-it-means-21" tabindex="-1">What it means <a class="header-anchor" href="#what-it-means-21" aria-label="Permalink to &quot;What it means&quot;">​</a></h3><p>Version history needs a signed-in workspace member. People who opened a share link don&#39;t see it, and presentations don&#39;t offer it on a phone.</p><h3 id="try-this-21" tabindex="-1">Try this <a class="header-anchor" href="#try-this-21" aria-label="Permalink to &quot;Try this&quot;">​</a></h3><ol><li>Sign in and open the document from your workspace&#39;s documents list.</li><li>For a presentation, use a window at least 768 pixels wide.</li></ol><h2 id="a-restore-is-already-in-progress" tabindex="-1"><code>A restore is already in progress</code> <a class="header-anchor" href="#a-restore-is-already-in-progress" aria-label="Permalink to &quot;`A restore is already in progress`&quot;">​</a></h2><h3 id="what-it-means-22" tabindex="-1">What it means <a class="header-anchor" href="#what-it-means-22" aria-label="Permalink to &quot;What it means&quot;">​</a></h3><p>A restore you started is still running. Wafflebase doesn&#39;t start another until it finishes.</p><h3 id="try-this-22" tabindex="-1">Try this <a class="header-anchor" href="#try-this-22" aria-label="Permalink to &quot;Try this&quot;">​</a></h3><ol><li>Wait a few seconds for the first restore to finish.</li><li>Try again.</li></ol><h2 id="couldn-t-update-the-workspace" tabindex="-1"><code>Couldn&#39;t update the workspace</code> <a class="header-anchor" href="#couldn-t-update-the-workspace" aria-label="Permalink to &quot;`Couldn&#39;t update the workspace`&quot;">​</a></h2><h3 id="what-it-means-23" tabindex="-1">What it means <a class="header-anchor" href="#what-it-means-23" aria-label="Permalink to &quot;What it means&quot;">​</a></h3><p>The change didn&#39;t go through. The most common causes: only workspace owners can change the workspace name and URL, and the URL may already be in use by another workspace.</p><h3 id="try-this-23" tabindex="-1">Try this <a class="header-anchor" href="#try-this-23" aria-label="Permalink to &quot;Try this&quot;">​</a></h3><ol><li>Ask a workspace owner to make the change.</li><li>If you are an owner, choose a different URL, check your connection, and try again.</li></ol><h2 id="this-server-is-too-old-for-desktop-sign-in" tabindex="-1"><code>This server is too old for desktop sign-in</code> <a class="header-anchor" href="#this-server-is-too-old-for-desktop-sign-in" aria-label="Permalink to &quot;`This server is too old for desktop sign-in` {#this-server-is-too-old-for-desktop-sign-in}&quot;">​</a></h2><h3 id="what-it-means-24" tabindex="-1">What it means <a class="header-anchor" href="#what-it-means-24" aria-label="Permalink to &quot;What it means&quot;">​</a></h3><p>The desktop app is connected to a Wafflebase server from before the app existed. That server can&#39;t sign you in from the app.</p><h3 id="try-this-24" tabindex="-1">Try this <a class="header-anchor" href="#try-this-24" aria-label="Permalink to &quot;Try this&quot;">​</a></h3><ol><li>Sign in from a web browser for now.</li><li>Ask your server&#39;s administrator to upgrade Wafflebase.</li><li>If you meant to use the official server, open <strong>Change server…</strong> and click <strong>Use wafflebase.io</strong>. See <a href="/docs/start/desktop.html#connect-to-your-team-s-server">Connect to your team&#39;s server</a>.</li></ol><h2 id="this-server-has-desktop-sign-in-turned-off" tabindex="-1"><code>This server has desktop sign-in turned off</code> <a class="header-anchor" href="#this-server-has-desktop-sign-in-turned-off" aria-label="Permalink to &quot;`This server has desktop sign-in turned off` {#this-server-has-desktop-sign-in-turned-off}&quot;">​</a></h2><h3 id="what-it-means-25" tabindex="-1">What it means <a class="header-anchor" href="#what-it-means-25" aria-label="Permalink to &quot;What it means&quot;">​</a></h3><p>The server isn&#39;t set up to sign in over HTTPS, so it refuses sign-in from the desktop app.</p><h3 id="try-this-25" tabindex="-1">Try this <a class="header-anchor" href="#try-this-25" aria-label="Permalink to &quot;Try this&quot;">​</a></h3><ol><li>Sign in from a web browser for now.</li><li>Ask your server&#39;s administrator to follow <a href="/docs/developers/self-hosting/sign-in.html#allow-desktop-app-sign-in">Allow desktop app sign-in</a>.</li></ol><h2 id="sign-in-timed-out-try-again" tabindex="-1"><code>Sign-in timed out. Try again.</code> <a class="header-anchor" href="#sign-in-timed-out-try-again" aria-label="Permalink to &quot;`Sign-in timed out. Try again.` {#sign-in-timed-out-try-again}&quot;">​</a></h2><h3 id="what-it-means-26" tabindex="-1">What it means <a class="header-anchor" href="#what-it-means-26" aria-label="Permalink to &quot;What it means&quot;">​</a></h3><p>The app waited five minutes for the browser to finish signing in, and it didn&#39;t.</p><h3 id="try-this-26" tabindex="-1">Try this <a class="header-anchor" href="#try-this-26" aria-label="Permalink to &quot;Try this&quot;">​</a></h3><ol><li>Close the Wafflebase sign-in tabs in your browser.</li><li>Click <strong>Continue with GitHub</strong> in the app again, and finish the steps in the browser tab it opens.</li></ol><h2 id="can-t-reach-appears-in-the-desktop-app" tabindex="-1"><strong>Can&#39;t reach</strong> appears in the desktop app <a class="header-anchor" href="#can-t-reach-appears-in-the-desktop-app" aria-label="Permalink to &quot;**Can&#39;t reach** appears in the desktop app {#can-t-reach-appears-in-the-desktop-app}&quot;">​</a></h2><h3 id="what-it-means-27" tabindex="-1">What it means <a class="header-anchor" href="#what-it-means-27" aria-label="Permalink to &quot;What it means&quot;">​</a></h3><p>The app can&#39;t connect to the server at the address it shows. Your computer may be offline, the address may be wrong, or the server may be down. The app keeps trying on its own.</p><h3 id="try-this-27" tabindex="-1">Try this <a class="header-anchor" href="#try-this-27" aria-label="Permalink to &quot;Try this&quot;">​</a></h3><ol><li>Check that your computer is connected to the internet. The app opens Wafflebase as soon as it is.</li><li>Click <strong>Try again</strong>.</li><li>Open the address in a web browser. If it doesn&#39;t open there either, ask your server&#39;s administrator.</li><li>If the address is wrong, click <strong>Change server…</strong> and enter the one you open Wafflebase at in a browser.</li></ol><h2 id="a-mac-says-wafflebase-is-damaged-or-can-t-be-opened" tabindex="-1">A Mac says Wafflebase is damaged or can&#39;t be opened <a class="header-anchor" href="#a-mac-says-wafflebase-is-damaged-or-can-t-be-opened" aria-label="Permalink to &quot;A Mac says Wafflebase is damaged or can&#39;t be opened {#a-mac-says-wafflebase-is-damaged-or-can-t-be-opened}&quot;">​</a></h2><h3 id="what-it-means-28" tabindex="-1">What it means <a class="header-anchor" href="#what-it-means-28" aria-label="Permalink to &quot;What it means&quot;">​</a></h3><p>The Mac app is signed and notarized by Apple, so a copy downloaded from the official link opens without a warning. A warning usually means the download was incomplete or the copy came from somewhere else.</p><h3 id="try-this-28" tabindex="-1">Try this <a class="header-anchor" href="#try-this-28" aria-label="Permalink to &quot;Try this&quot;">​</a></h3><ol><li>Move the Wafflebase app you installed to the Trash.</li><li>Download it again from the link in <a href="/docs/start/desktop.html#install-on-a-mac">Install on a Mac</a>, and install it.</li></ol><h2 id="still-stuck" tabindex="-1">Still stuck <a class="header-anchor" href="#still-stuck" aria-label="Permalink to &quot;Still stuck&quot;">​</a></h2><p>Report the problem on <a href="https://github.com/wafflebase/wafflebase/issues" target="_blank" rel="noreferrer">GitHub Issues</a>. Include the exact message, the document type, and your browser or app.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/docs/start/concepts.html">Concepts</a>: who can see and change what</li><li><a href="/docs/collaborate/share.html">Share a document</a>: create and revoke share links</li><li><a href="/docs/collaborate/trash.html">Trash</a>: restore deleted documents</li><li><a href="/docs/collaborate/version-history.html">Version history</a>: preview and restore earlier versions</li></ul>',161)])])}const p=a(r,[["render",s]]);export{m as __pageData,p as default};
